    /// <summary>
    /// MPJ_21275_BackOrders
    /// Modify based on the user selected back order parameter and it will give an info
    /// </summary>
    /// <param name="sender">form datasource</param>
    /// <param name="e">Data field</param>
    [
        FormDataFieldEventHandler(formDataFieldStr(CustTable, METCustTable, AllowBackOrders), FormDataFieldEventType::Modified),
        SuppressBPWarningAttribute('BPParameterNotUsed', "@MET:BPParameterNotUsedMessage")
    ]
    public static void AllowBackOrders_OnModified(FormDataObject sender, FormDataFieldEventArgs e)
    {
        FormDataSource  metCustTable_ds   = sender.datasource();
        METCustTable    metCustTable      = metCustTable_ds.cursor();
        DialogButton    dialogButton;
        
        if (metCustTable.AllowBackOrders == NoYes::No)
        {
            dialogButton = Box::yesNo("@MET:METCustomerMasterDisableBackOrder", DialogButton::Yes);
            
            if (dialogButton == DialogButton::No)
            {
                metCustTable.AllowBackOrders = NoYes::Yes;
            }
            else
            {
                metCustTable.AllowBackOrders = NoYes::No;
            }
        }

        else if (metCustTable.AllowBackOrders == NoYes::Yes)
        {
            dialogButton = Box::yesNo("@MET:METCustomerMasterActivateBackOrder", DialogButton::Yes);
            
            if (dialogButton == DialogButton::No)
            {
                metCustTable.AllowBackOrders = NoYes::No;
            }
            else
            {
                metCustTable.AllowBackOrders = NoYes::Yes;
            }
        }
    }

/// <summary>
/// MPJ_26957_AllowBackOrders
/// Activate the customer header level allowback order based on cust parameter
/// </summary>
/// <param name="sender">Form Data source</param>
/// <param name="e">Form data source event</param>
[FormDataSourceEventHandler(formDataSourceStr(CustTable, METCustTable), FormDataSourceEventType::Activated),
    SuppressBPWarningAttribute('BPParameterNotUsed', "@MET:BPParameterNotUsedMessage")]
public static void METCustTable_OnActivated(FormDataSource sender, FormDataSourceEventArgs e)
{
    METCustTable        metCustTable    = sender.cursor();
    FormCheckboxControl backorder       = sender.formRun().design(0).controlName(formControlStr(CustTable, BackOrders_AllowBackOrders));

    if(CustParameters::find().METAllowBackOrders == NoYes::Yes)
    {
        backorder.allowEdit(true);
    }
    else
    {
        metCustTable.AllowBackOrders = NoYes::No;
        backorder.allowEdit(false);
    }
}
